mapper.select:
SELECT pp.id, pp.code, pp.create_user_id AS createUserId, pp.create_user_name AS createUserName, pp.create_time AS createTime, pp.supplier_id AS supplierId, (SELECT name FROM supplier WHERE id=pp.supplier_id) AS supplierName, ppd.sku_id AS skuId, ppd.sku_no AS skuNo, ppd.product_name AS productName,ppd.min_qty as minQty,ppd.max_qty as maxQty, pp.approve_status as approveStatus, ppd.tax_price as taxPrice, ppd.currency, ppd.tax_rate*100 AS taxRate , ppd.effective_date AS effectiveDate, ppd.expire_date AS expireDate, pp.purchase_org_id as purchase_Org_Id, pp.purchase_org_name as purchaseOrgName, ppd.id AS purchasePriceDetailId, ppd.disabled, ppd.remark as detailRemark, pp.approve_time, ppd.delivery_day FROM purchase_price_detail ppd INNER JOIN purchase_price pp ON ppd.purchase_price_id=pp.id WHERE ${params.sqlMap.default} and pp.is_deleted = false AND ppd.is_deleted= false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC,ppd.id DESC

SELECT pp.id, pp.code, pp.create_user_id AS createUserId, pp.create_user_name AS createUserName, pp.create_time AS createTime, pp.supplier_id AS supplierId, (SELECT name FROM supplier WHERE id=pp.supplier_id) AS supplierName, ppd.sku_id AS skuId, ppd.sku_no AS skuNo, ppd.product_name AS productName,ppd.min_qty AS minQty,ppd.max_qty AS maxQty, pp.approve_status AS approveStatus, ppd.tax_price AS taxPrice, ppd.tax_rate*100 AS taxRate , ppd.effective_date AS effectiveDate, ppd.expire_date AS expireDate, ppd.currency, pp.purchase_org_id AS purchaseOrgId, pp.purchase_org_name AS purchaseOrgName, PPd.disabled, pp.approve_time FROM purchase_price_detail ppd LEFT JOIN purchase_price pp ON ppd.purchase_price_id=pp.id WHERE ${params.sqlMap.default} and pp.is_deleted=false AND ppd.is_deleted= false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC,ppd.id DESC

SELECT p.supplier_id, p.sku_id, p.sku_no, p.tax_price, p.tax_rate, p.currency from( SELECT pp.supplier_id, ppd.sku_id, ppd.sku_no, ppd.tax_price, ppd.tax_rate, ppd.min_qty, ppd.currency, row_number() over(partition by pp.supplier_id, ppd.sku_id, ppd.sku_no order by ppd.min_qty ASC,ppd.update_time desc) as rank FROM purchase_price pp LEFT JOIN purchase_price_detail ppd ON pp.id = ppd.purchase_price_id and ppd.is_deleted = false WHERE pp.is_deleted = false and approve_status = 'approve' AND pp.supplier_id IN
#{id}
) p WHERE p.rank=1

select count(distinct pp.id) from purchase_price pp left join purchase_price_detail ppd on pp.id = ppd.purchase_price_id and ppd.is_deleted = false
${params.sqlMap.default} and pp.is_deleted = false
${params.permissionSql}
